  $$("[data-tab]").forEach(button => {
    const active = button.dataset.tab === category;
    button.setAttribute("aria-selected",String(active));
    button.tabIndex = active ? 0 : -1;
  });
  const content = focusContent[language][category];
  $("#expertise-panel").setAttribute("aria-labelledby","tab-"+category);
  $("#expertise-number").textContent = content.number;
  $("#expertise-image-label").textContent = content.label;
  $("#expertise-title").innerHTML = content.title;
  $("#expertise-description").textContent = content.body;
  $("#expertise-detail-one").textContent = content.one;
  $("#expertise-detail-two").textContent = content.two;
  const image = $("#expertise-photo");
  image.src = "assets/"+content.image+".webp";
  image.alt = content.alt;
